static esp_err_t meeting_minutes_visualizer_levels(const int16_t samples[MEETING_MINUTES_VIS_FFT_SIZE],
                                                   float *window,
                                                   float *fft_buf,
                                                   uint8_t levels[MEETING_MINUTES_VIS_BARS])
{
    if (samples == NULL || window == NULL || fft_buf == NULL || levels == NULL) {
        return ESP_ERR_INVALID_ARG;
    }

    for (uint32_t i = 0; i < MEETING_MINUTES_VIS_FFT_SIZE; i++) {
        fft_buf[2 * i] = ((float)samples[i] / 32768.0f) * window[i];
        fft_buf[2 * i + 1] = 0.0f;
    }

    dsps_fft2r_fc32(fft_buf, MEETING_MINUTES_VIS_FFT_SIZE);
    dsps_bit_rev_fc32(fft_buf, MEETING_MINUTES_VIS_FFT_SIZE);

    const uint32_t half_bins = MEETING_MINUTES_VIS_FFT_SIZE / 2;
    for (uint32_t band = 0; band < MEETING_MINUTES_VIS_BARS; band++) {
        uint32_t start_bin = meeting_minutes_log_bin_start(band, MEETING_MINUTES_VIS_BARS, half_bins);
        uint32_t end_bin = meeting_minutes_log_bin_start(band + 1, MEETING_MINUTES_VIS_BARS, half_bins);
        if (end_bin <= start_bin) {
            end_bin = start_bin + 1;
        }
        if (end_bin > half_bins) {
            end_bin = half_bins;
        }

        float peak = 0.0f;
        for (uint32_t bin = start_bin; bin < end_bin; bin++) {
            float real = fft_buf[2 * bin];
            float imag = fft_buf[2 * bin + 1];
            float mag = sqrtf(real * real + imag * imag);
            if (mag > peak) {
                peak = mag;
            }
        }
        float db = 20.0f * log10f((peak + 1e-9f) / (float)MEETING_MINUTES_VIS_FFT_SIZE);
        levels[band] = meeting_minutes_db_to_level(db);
    }
    return ESP_OK;
}

static esp_err_t meeting_minutes_visualizer_time_levels(const int16_t samples[MEETING_MINUTES_VIS_FFT_SIZE],
                                                        uint8_t levels[MEETING_MINUTES_VIS_BARS])
{
    if (samples == NULL || levels == NULL) {
        return ESP_ERR_INVALID_ARG;
    }

    int64_t sum_sq = 0;
    for (uint32_t i = 0; i < MEETING_MINUTES_VIS_FFT_SIZE; i++) {
        int32_t s = samples[i];
        sum_sq += (int64_t)s * s;
    }
    float rms = sqrtf((float)sum_sq / (float)MEETING_MINUTES_VIS_FFT_SIZE) / 32768.0f;
    float db = 20.0f * log10f(rms + 1e-9f);
    uint8_t level = meeting_minutes_db_to_level(db);

    memmove(&s_meeting_minutes_time_levels[0],
            &s_meeting_minutes_time_levels[1],
            MEETING_MINUTES_VIS_BARS - 1);
    s_meeting_minutes_time_levels[MEETING_MINUTES_VIS_BARS - 1] = level;
    for (size_t i = 0; i < MEETING_MINUTES_VIS_BARS; i++) {
        levels[i] = s_meeting_minutes_time_levels[MEETING_MINUTES_VIS_BARS - 1 - i];
    }
    return ESP_OK;
}

