esp_err_t system_ui_create_meeting_minutes_locked(void)
{
    meeting_minutes_screen_init();
    ESP_RETURN_ON_FALSE(ui_Screen2 != NULL, ESP_ERR_NO_MEM,
                        SYSTEM_UI_TAG, "create meeting minutes screen failed");
    s_ui.meeting_minutes_screen = ui_Screen2;
    ESP_LOGI(SYSTEM_UI_TAG, "meeting minutes screen created");
    return ESP_OK;
}

void system_ui_delete_meeting_minutes_locked(void)
{
    meeting_minutes_screen_destroy();
    s_ui.meeting_minutes_screen = NULL;
    s_ui.meeting_minutes_visible = false;
}

esp_err_t system_ui_show_meeting_minutes(void)
{
    ESP_RETURN_ON_FALSE(s_ui.started && s_ui.meeting_minutes_screen, ESP_ERR_INVALID_STATE,
                        SYSTEM_UI_TAG, "meeting minutes screen not available");
    ESP_RETURN_ON_FALSE(!display_service_has_exclusive_session(), ESP_ERR_INVALID_STATE,
                        SYSTEM_UI_TAG, "exclusive display session active");
    ESP_RETURN_ON_ERROR(system_ui_lock(), SYSTEM_UI_TAG, "lock failed");
    s_ui.meeting_minutes_visible = true;
    system_ui_load_screen_locked(s_ui.meeting_minutes_screen);
    system_ui_unlock();
    return ESP_OK;
}

esp_err_t system_ui_hide_meeting_minutes(void)
{
    ESP_RETURN_ON_FALSE(s_ui.started && s_ui.home_screen, ESP_ERR_INVALID_STATE,
                        SYSTEM_UI_TAG, "home screen not available");
    ESP_RETURN_ON_ERROR(system_ui_lock(), SYSTEM_UI_TAG, "lock failed");
    meeting_minutes_stop_recording();
    s_ui.meeting_minutes_visible = false;
    ui_squareline_show_page(ui_squareline_current_page());
    system_ui_load_screen_locked(s_ui.home_screen);
    system_ui_unlock();
    return ESP_OK;
}
